212	/**
213	 * Emit, on the "liastar-ext-smt" channel, the queries validating the
214	 * membership encoding: one query per disjunct asserting it differs from the
215	 * predicate cell it encodes, and a final query asserting the whole predicate
216	 * (lambda[1]) differs from the disjunction of all membership formulas. All of
217	 * them must be unsat when the trace is replayed.
218	 */
219	void traceMembershipValidation(NodeManager* nm,
220	                               Node lambda,
221	                               const std::vector<std::pair<Node, Node>>& lia)
222	{
223	  for (size_t i = 0; i < lia.size(); i++)
224	  {
225	    LiaStarUtils::traceDistinctQuery(
226	        std::to_string(i), lia[i].first, lia[i].second);
227	  }
228	  std::vector<Node> disjunctions;
229	  std::transform(
230	      lia.begin(), lia.end(), std::back_inserter(disjunctions), [](auto& p) {
231	        return p.second;
232	      });
233	  Node liaFormula;
234	  if (disjunctions.size() == 0)
235	  {
236	    liaFormula = nm->mkConst(false);
237	  }
238	  else if (disjunctions.size() == 1)
239	  {
240	    liaFormula = disjunctions[0];
241	  }
242	  else
243	  {
244	    liaFormula = nm->mkNode(Kind::OR, disjunctions);
245	  }
246	  LiaStarUtils::traceDistinctQuery("lia formula: ", lambda[1], liaFormula);
247	}
