276	void LiaStarExtension::preRegisterTerm(TNode n)
277	{
278	  // register terms with extended theory, to find extended terms that can be
279	  // eliminated by context-dependent simplification.
280	  if (d_extTheory.hasFunctionKind(n.getKind()))
281	  {
282	    d_hasLiaStarTerms = true;
