1004	void LiaStarUtils::getGeneratorBody(
1005	    size_t dimension,
1006	    const std::vector<Integer>& generator,
1007	    const std::vector<std::vector<Integer>>& hilbertBasis,
1008	    bool star,
1009	    bool useSkolems,
1010	    NodeManager* nm,
1011	    std::vector<Node>& vars,
1012	    std::vector<Node>& constraints,
1013	    std::vector<Node>& point,
