1017	  // by `hilbertBasis = {h_1, ..., h_m}`. The integer points reachable from this
1018	  // generator are `g + sum_j l_j * h_j` for non-negative integers l_j. There
1019	  // are two flavours:
1020	  //
1021	  //   membership (star == false): the contribution of this generator is the
1022	  //     point `g + sum_j l_j h_j`, with `g` a fixed offset (multiplier 1). Used
1023	  //     to express that the vector is a single member of the set.
1024	  //
1025	  //   star (star == true): the generator may be used `mu >= 0` times, so its
1026	  //     contribution is `mu * g + sum_j l_j h_j`, with the coupling
1027	  //     `mu = 0 => l_j = 0` (a ray can only be taken if its generator is). This
1028	  //     encodes membership in the additive closure (the star).
1029	  //
1030	  // The fresh multipliers (`mu` and the `l_j`) are skolem constants when
1031	  // `useSkolems` (the constraints are asserted at the top level) or bound
1032	  // variables otherwise (the caller existentially binds them).
1033	  Node zero = nm->mkConstInt(Rational(0));
1034	  Node one = nm->mkConstInt(Rational(1));
1035	  std::vector<Integer> zeroVector(dimension, Integer(0));
1036	
1037	  // The multiplier for the module generator. In the membership encoding the
1038	  // generator is a fixed offset (multiplier 1). In the star encoding it is a
1039	  // fresh variable counting how many times the generator is used, except for
1040	  // the zero generator (the cone's homogeneous part) which is always present
1041	  // once.
1042	  Node mu = one;
1043	  if (star && generator != zeroVector)
1044	  {
1045	    mu = useSkolems ? nm->mkDummySkolem("mu", nm->integerType())
1046	                    : nm->mkBoundVar("mu", nm->integerType());
